import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/domain/usecases/login.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/domain/usecases/logout.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/domain/usecases/register.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/presentation/controllers/auth_controller.dart';import 'package:repo_aksomda_lifetownnightclub/features/auth/presentation/pages/login_page.dart';import 'mocks/mock_auth_repository.dart';
void main(){testWidgets('l’utilisateur peut se connecter',(tester)async{final repo=MockAuthRepository();final controller=AuthController(loginUseCase:Login(repo),registerUseCase:Register(repo),logoutUseCase:Logout(repo));await tester.pumpWidget(MaterialApp(home:LoginPage(controller:controller,onRegister:(){})));await tester.enterText(find.byType(TextFormField).at(0),'admin@lifetown.com');await tester.enterText(find.byType(TextFormField).at(1),'password');await tester.tap(find.text('Se connecter'));await tester.pumpAndSettle();expect(controller.isAuthenticated,true);expect(find.text('LIFETOWN'),findsOneWidget);});testWidgets('un email invalide bloque la connexion',(tester)async{final controller=AuthController(loginUseCase:Login(MockAuthRepository()),registerUseCase:Register(MockAuthRepository()),logoutUseCase:Logout(MockAuthRepository()));await tester.pumpWidget(MaterialApp(home:LoginPage(controller:controller,onRegister:(){})));await tester.enterText(find.byType(TextFormField).at(0),'bad');await tester.enterText(find.byType(TextFormField).at(1),'password');await tester.tap(find.text('Se connecter'));await tester.pump();expect(find.text('Email invalide'),findsOneWidget);});}
